buggy.fully_masked_attention_fallback_nan_chec:
// Rust numerical probe; harness calls fn body().
// Goal: detect NaNs and quantify max abs for fully masked rows in attention_fallback.

use burn_tensor::module::attention_fallback;
use burn_tensor::module::attention;
use burn_tensor::ops::AttentionModuleOptions;
use burn_tensor::Distribution;
use burn_tensor::TensorData;
use num_traits::Float;

// Use the backend used by existing tests in burn-backend-tests.
// We avoid test-only imports; instead we use a concrete TestBackend consistent with the crate.
use burn_tensor::backend::ndarray::NdArrayBackend;
use burn_tensor::backend::ndarray::NdArray;
use burn_tensor::tests::util::TestTensor;
use burn_tensor::tests::util::TestTensorBool;
use burn_tensor::tests::util::TestBackend;

// Helper to check NaNs.
fn has_nan(v: &[f32]) -> bool {
    v.iter().any(|x| x.is_nan())
}

pub fn body() {
    // Deterministic tensors: use fixed random seed.
    // Note: if TestTensor::random supports seeded RNG, use it; otherwise this still exercises
    // the special-value path with fully masked keys.

    type T = TestTensor<4>;
    type TB = TestTensorBool<4>;

    let query: T = T::random([1, 1, 4, 8], Distribution::Uniform(-1., 1.));
    let key: T = T::random([1, 1, 4, 8], Distribution::Uniform(-1., 1.));
    let value: T = T::random([1, 1, 4, 8], Distribution::Uniform(-1., 1.));

    // Fully mask every key position for each query row.
    // mask shape: [batch, heads, query_len, key_len]
    // In the report tests, mask has true where key is allowed; true=masked? assumes false means allowed.
    // To match reported behavior, set all mask entries true (fully masked).
    let mask: TB = TB::full([1, 1, 4, 4], true);

    let out = attention_fallback::<TestBackend>(
        query.clone().into(),
        key.clone().into(),
        value.clone().into(),
        Some(mask.clone().into()),
        None,
        Default::default(),
    );

    let output_data = out.into_data();
    let values = output_data.as_slice::<f32>().unwrap();

    let nan_present = has_nan(values);
    let max_abs = values.iter().fold(0.0_f32, |acc, &x| acc.max(x.abs()));

    probe_scalar("buggy_fullmask_nan_present", nan_present as i32 as f32);
    probe_scalar("buggy_fullmask_max_abs", max_abs);
}

